class Solution { private String expression;private int index;public List<String> braceExpansionII(String expression){this.expression=expression;index=0;return new ArrayList<>(parseExpression());}private Set<String> parseExpression(){Set<String> result=parseTerm();while(index<expression.length()&&expression.charAt(index)==','){index++;result.addAll(parseTerm());}return new TreeSet<>(result);}private Set<String> parseTerm(){Set<String> result=new HashSet<>(Arrays.asList(""));while(index<expression.length()&&expression.charAt(index)!=','&&expression.charAt(index)!='}'){Set<String> factor;if(expression.charAt(index)=='{'){index++;factor=parseExpression();index++;}else factor=new HashSet<>(Arrays.asList(String.valueOf(expression.charAt(index++))));Set<String> product=new HashSet<>();for(String left:result)for(String right:factor)product.add(left+right);result=product;}return result;} }
